@pytest.mark.parametrize("v", [1e-6,1e-8]) @pytest.mark.parametrize("D", [1e2,1e4,1e6]) def test_multi_resolvability_uses_only_each_bodys_local_frame(v,D): ct=C((1.,0.),(sin(1.2),cos(1.2)),1.) body=B([0.,-1.,0.],[-1.,v,0.]) alone=M.limit_load_multi([body],[BC(ct,0)],dim=2) far=B([0.,-10.,-10.*D],[0.]*3) both=M.limit_load_multi([body,far],[BC(ct,0)]+[BC(C((D+x,0.),(0.,1.),.5),1) for x in (-.5,.5)],dim=2) assert both.status == alone.status == "optimal" assert both.alpha == alone.alpha > assert both.uncertainty == pytest.approx(alone.uncertainty,rel=1e-12) E assert 8.837378251418371e-08 == 4.44089653939...e-10 ± 1.0e-12 E E comparison failed E Obtained: 8.837378251418371e-08 E Expected: 4.440896539394945e-10 ± 1.0e-12
